mapper.select:
SELECT tlal.user, IF(MIN(tlal.create_time) BETWEEN #{startDate} AND #{endDate}, '新访客', '老访客') AS uvType FROM t_link tl INNER JOIN t_link_access_logs tlal ON tl.full_short_url = tlal.full_short_url WHERE tlal.full_short_url = #{fullShortUrl} AND tl.gid = #{gid} AND tl.del_flag = '0' AND tl.enable_status = #{enableStatus} AND tlal.user IN
#{user}
GROUP BY tlal.user

SELECT tlal.user, IF(MIN(tlal.create_time) BETWEEN #{startDate} AND #{endDate}, '新访客', '老访客') AS uvType FROM t_link tl INNER JOIN t_link_access_logs tlal ON tl.full_short_url = tlal.full_short_url WHERE tl.gid = #{gid} AND tl.del_flag = '0' AND tl.enable_status = '0' AND tlal.user IN
#{user}
GROUP BY tlal.user

SELECT tlal.full_short_url,
       tl.gid,
       count(tlal.user)          AS pv,
       count(DISTINCT tlal.user) AS uv,
       count(DISTINCT tlal.ip)   AS uip
FROM t_link tl
         INNER JOIN
     t_link_access_logs tlal ON
         tl.full_short_url = tlal.full_short_url
WHERE tl.gid = #{bean.gid}
  AND tlal.full_short_url = #{bean.fullShortUrl}
  AND tlal.create_time BETWEEN #{bean.startDate} and #{bean.endDate}
  AND tl.del_flag = '0'
  AND tl.enable_status = #{bean.enableStatus}
GROUP BY tlal.full_short_url,
         tl.gid;

SELECT tlal.ip,
       count(*) AS cnt
FROM t_link tl
         INNER JOIN
     t_link_access_logs tlal ON
         tl.full_short_url = tlal.full_short_url
WHERE tlal.full_short_url = #{bean.fullShortUrl}
  AND tl.gid = #{bean.gid}
  AND tlal.`date` BETWEEN #{bean.startDate} AND #{bean.endDate}
  AND tl.del_flag = '0'
  AND tl.enable_status = #{bean.enableStatus}
GROUP BY tl.gid,
         tlal.full_short_url,
         tlal.ip
LIMIT 5;

SELECT SUM(old_user) as oldUserCnt,
       SUM(new_user) as newUserCnt
FROM (SELECT IF(COUNT(distinct DATE(tlal.create_time)) > 1, 1, 0) as old_user,
             IF(COUNT(distinct DATE(tlal.create_time)) = 1 and MAX(tlal.create_time) >= #{bean.startDate} and
                MAX(tlal.create_time) <= #{bean.endDate}, 1, 0)   as new_user
      FROM t_link tl
               INNER JOIN
           t_link_access_logs tlal ON
               tl.full_short_url = tlal.full_short_url
      WHERE tl.gid = #{bean.gid}
        AND tlal.full_short_url = #{bean.fullShortUrl}
        AND tlal.`date` BETWEEN #{bean.startDate} AND #{bean.endDate}
        AND tl.del_flag = '0'
        AND tl.enable_status = #{bean.enableStatus}
      GROUP BY tlal.user) AS user_counts;
